function stageProgressMarkup(stage) { const names = stageNames[language] || stageNames.en; const level = stageLevelLabels[language] || stageLevelLabels.en; const keys = Object.keys(stageIcons); return keys.map((key, index) => `<div class="stage-chip ${key === stage ? 'active' : ''} ${keys.indexOf(stage) > index ? 'complete' : ''}" data-stage-key="${key}" role="button" tabindex="0" aria-current="${key === stage ? 'step' : 'false'}"><span class="stage-chip-icon">${stageIcons[key]}</span><span class="stage-chip-copy"><b>${level} ${names[key]}</b></span></div>${index < keys.length - 1 ? '<span class="stage-connector" aria-hidden="true">→</span>' : ''}`).join(''); }
