function explanationAnswerKey(key) { return `${key}Answer`; }
function recordSnapshot() { return { participantId: participant.id, surveyLanguage: participant.surveyLanguage || language, demographics: participant.demographics || {}, rewardCharacter: participant.rewardCharacter, rewardMessage: participant.rewardMessage, dinosaurFact: participant.dinosaurFact, responses, updatedAt: new Date().toISOString() }; }
function upsertRecord() { const records = JSON.parse(localStorage.getItem('robotStudyRecords') || '[]'); const record = recordSnapshot(); const index = records.findIndex(item => item.participantId === record.participantId); if (index >= 0) records[index] = record; else records.push(record); localStorage.setItem('robotStudyRecords', JSON.stringify(records)); }
function save() { localStorage.setItem('robotStudyResponses', JSON.stringify(responses)); upsertRecord(); updateChrome(); }
