function explanationMarkup() { if (explanationLoading) return '<div class="answer-loading">Preparing the robot’s explanation…</div>'; if (explanationError) return `<div class="error">${escapeMarkup(explanationError)}</div>`; if (!answerVisible || !explanationResponse) return ''; return `<div class="answer-box robot-response"><div class="robot-avatar" aria-hidden="true"><svg viewBox="0 0 64 64" role="img"><path d="M32 9v7"/><circle cx="32" cy="6" r="3"/><rect x="13" y="16" width="38" height="31" rx="9"/><circle cx="25" cy="30" r="4"/><circle cx="39" cy="30" r="4"/><path d="M24 39c5 4 11 4 16 0M13 27H7m50 0h-6"/></svg></div><div><strong>${ui().robotExplanation}</strong><p>${escapeMarkup(explanationResponse).replace(/\n/g, '<br>')}</p></div></div>`; }
