  if (step.type === 'demographics') { const d = participant.demographics || {}; const demo = locales[language].demographics; const university = d.education === 'University degree' || d.education === 'Título universitario' || d.education === 'شهادة جامعية' || d.education === 'Diplôme universitaire'; html = `<div class="panel"><p class="eyebrow">${demo.label}</p><h2>${demo.title}</h2><div class="form-grid"><div><label class="field-label">${demo.gender}</label><div class="inline-options">${demo.genderOptions.map((o, i) => `<label class="choice compact"><input type="radio" name="gender" value="${o}" ${d.gender === o ? 'checked' : ''}><b>${o}</b></label>`).join('')}</div></div><div><label class="field-label" for="age">${demo.age}</label><input class="text-input" id="age" type="number" min="1" max="120" placeholder="${demo.agePlaceholder}" value="${d.age || ''}"></div></div><label class="field-label" for="education">${demo.education}</label><select class="text-input" id="education"><option value="">—</option>${demo.educationOptions.map(o => `<option ${d.education === o ? 'selected' : ''}>${o}</option>`).join('')}</select>${university ? `<div class="conditional-question"><label class="field-label">${demo.technology}</label><div class="inline-options"><label class="choice compact"><input type="radio" name="technology" value="${demo.yes}" ${d.technology === demo.yes ? 'checked' : ''}><b>${demo.yes}</b></label><label class="choice compact"><input type="radio" name="technology" value="${demo.no}" ${d.technology === demo.no ? 'checked' : ''}><b>${demo.no}</b></label></div></div>` : ''}${actions()}</div>`; }
  if (step.type === 'video') html = `<div class="panel video-intro-panel"><p class="eyebrow">${step.label}</p><h2>${step.title}</h2><p class="form-hint">The video is shown above. Please watch it until the end before continuing.</p>${actions(true)}</div>`;
  if (step.type === 'scale') html = `<div class="panel"><p class="eyebrow">${step.label}</p><div class="question-head"><h2>${step.title}</h2>${step.info ? `<button class="info-btn" data-action="info" aria-label="${ui().info}">i</button>` : ''}</div>${step.info ? `<div class="info-box" id="info-box">${ui().info}</div>` : ''}${step.example ? `<div class="question-example"><strong>Example</strong>${step.example}</div>` : ''}<div class="choices">${step.options.map(o => `<label class="choice ${responses[step.key] === o ? 'selected' : ''}"><input type="radio" name="${step.key}" value="${o}" ${responses[step.key] === o ? 'checked' : ''}><span class="choice-copy"><b>${o}</b></span></label>`).join('')}</div>${actions()}</div>`;
